def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C' if n % 2 == 0 else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = 0
    for x in opp:
        if x == 'D':
            opp_d += 1
    opp_c = n - opp_d
    my_d = 0
    for x in me:
        if x == 'D':
            my_d += 1

    last1 = opp[-1]
    last2 = opp[-2] if n >= 2 else 'C'
    last3 = opp[-3] if n >= 3 else 'C'

    ret = 0
    for i in range(1, n):
        if me[i-1] == 'D' and opp[i] == 'D':
            ret += 1

    if n >= 99:
        return 'D'
    if n == 98:
        return 'D' if ret == 0 else 'C'

    if last1 == 'D' and last2 == 'D':
        return 'D'
    if opp_d >= 3 and opp_d >= 2 * opp_c:
        return 'D'
    if n >= 4 and opp[-4:] == ['D', 'C', 'D', 'C']:
        return 'D'
    if n >= 4 and opp[-4:] == ['C', 'D', 'C', 'D']:
        return 'C'
    if my_d == 0 and opp_d >= 2:
        return 'D'
    if last1 == 'D' and last2 == 'C' and last3 == 'C':
        return 'C'
    if last1 == 'C':
        return 'C'
    if rng.random() < 0.25:
        return 'C'
    return 'D'
